-- Additive operation history and content-addressed assets; old rows and counters are untouched.
CREATE TABLE github_connections (owner_id TEXT NOT NULL, app_id TEXT NOT NULL, version INTEGER NOT NULL CHECK(version BETWEEN 1 AND 9007199254740991), data TEXT NOT NULL CHECK(json_valid(data)), stored_bytes INTEGER NOT NULL CHECK(stored_bytes BETWEEN 1 AND 1048576), PRIMARY KEY(owner_id,app_id,version), FOREIGN KEY(owner_id,app_id) REFERENCES applications(owner_id,id), CHECK(stored_bytes=length(CAST(json_array(owner_id,app_id,version,data) AS BLOB)))) STRICT;
CREATE TABLE github_detections (owner_id TEXT NOT NULL, app_id TEXT NOT NULL, id TEXT NOT NULL CHECK(length(id) BETWEEN 1 AND 96), created_at INTEGER NOT NULL CHECK(created_at BETWEEN 0 AND 9007199254740991), data TEXT NOT NULL CHECK(json_valid(data)), stored_bytes INTEGER NOT NULL CHECK(stored_bytes BETWEEN 1 AND 1048576), PRIMARY KEY(owner_id,app_id,id), FOREIGN KEY(owner_id,app_id) REFERENCES applications(owner_id,id), CHECK(stored_bytes=length(CAST(json_array(owner_id,app_id,id,created_at,data) AS BLOB)))) STRICT;
CREATE TABLE ota_assets (owner_id TEXT NOT NULL, app_id TEXT NOT NULL, hash TEXT NOT NULL CHECK(length(hash)=64 AND hash NOT GLOB '*[^a-f0-9]*'), byte_length INTEGER NOT NULL CHECK(byte_length BETWEEN 1 AND 16777216), content_type TEXT NOT NULL CHECK(length(content_type) BETWEEN 1 AND 256), chunk_count INTEGER NOT NULL CHECK(chunk_count BETWEEN 1 AND 32), data TEXT NOT NULL CHECK(json_valid(data)), stored_bytes INTEGER NOT NULL CHECK(stored_bytes BETWEEN 1 AND 1048576), PRIMARY KEY(owner_id,app_id,hash), FOREIGN KEY(owner_id,app_id) REFERENCES applications(owner_id,id), CHECK(stored_bytes=length(CAST(json_array(owner_id,app_id,hash,byte_length,content_type,chunk_count,data) AS BLOB)))) STRICT;
CREATE TABLE ota_asset_chunks (owner_id TEXT NOT NULL, app_id TEXT NOT NULL, hash TEXT NOT NULL, chunk_index INTEGER NOT NULL CHECK(chunk_index BETWEEN 0 AND 31), content_base64 TEXT NOT NULL CHECK(length(content_base64)<=699052), byte_length INTEGER NOT NULL CHECK(byte_length BETWEEN 1 AND 524288), stored_bytes INTEGER NOT NULL CHECK(stored_bytes BETWEEN 1 AND 1048576), PRIMARY KEY(owner_id,app_id,hash,chunk_index), FOREIGN KEY(owner_id,app_id,hash) REFERENCES ota_assets(owner_id,app_id,hash), CHECK(stored_bytes=length(CAST(json_array(owner_id,app_id,hash,chunk_index,content_base64,byte_length) AS BLOB)))) STRICT;
CREATE TABLE ota_deployments (owner_id TEXT NOT NULL, app_id TEXT NOT NULL, id TEXT NOT NULL CHECK(length(id) BETWEEN 1 AND 96), request_key TEXT NOT NULL CHECK(length(request_key) BETWEEN 1 AND 256), channel TEXT NOT NULL CHECK(length(channel) BETWEEN 1 AND 128), runtime_version TEXT NOT NULL CHECK(length(runtime_version) BETWEEN 1 AND 256), platform TEXT NOT NULL CHECK(platform IN ('ios','android')), created_at INTEGER NOT NULL CHECK(created_at BETWEEN 0 AND 9007199254740991), data TEXT NOT NULL CHECK(json_valid(data)), stored_bytes INTEGER NOT NULL CHECK(stored_bytes BETWEEN 1 AND 1048576), PRIMARY KEY(owner_id,app_id,id), UNIQUE(owner_id,app_id,request_key), FOREIGN KEY(owner_id,app_id) REFERENCES applications(owner_id,id), CHECK(stored_bytes=length(CAST(json_array(owner_id,app_id,id,request_key,channel,runtime_version,platform,created_at,data) AS BLOB)))) STRICT;
CREATE TABLE ota_deployment_assets (owner_id TEXT NOT NULL, app_id TEXT NOT NULL, deployment_id TEXT NOT NULL, hash TEXT NOT NULL, stored_bytes INTEGER NOT NULL CHECK(stored_bytes BETWEEN 1 AND 1048576), PRIMARY KEY(owner_id,app_id,deployment_id,hash), FOREIGN KEY(owner_id,app_id,deployment_id) REFERENCES ota_deployments(owner_id,app_id,id), FOREIGN KEY(owner_id,app_id,hash) REFERENCES ota_assets(owner_id,app_id,hash), CHECK(stored_bytes=length(CAST(json_array(owner_id,app_id,deployment_id,hash) AS BLOB)))) STRICT;
DROP TRIGGER capacity_integrity;
CREATE TRIGGER capacity_integrity BEFORE UPDATE ON flora_capacity WHEN NEW.singleton<>1 OR NEW.snapshot_count<>(SELECT count(*) FROM inventory_snapshots) OR NEW.baseline_count<>(SELECT count(*) FROM baseline_imports) OR NEW.payload_bytes<>(SELECT coalesce(sum(stored_bytes),0) FROM inventory_snapshots)+(SELECT coalesce(sum(stored_bytes),0) FROM baseline_imports)+(SELECT coalesce(sum(stored_bytes),0) FROM source_head_observations)+(SELECT coalesce(sum(stored_bytes),0) FROM applications)+(SELECT coalesce(sum(stored_bytes),0) FROM application_settings)+(SELECT coalesce(sum(stored_bytes),0) FROM github_connections)+(SELECT coalesce(sum(stored_bytes),0) FROM github_detections)+(SELECT coalesce(sum(stored_bytes),0) FROM ota_assets)+(SELECT coalesce(sum(stored_bytes),0) FROM ota_asset_chunks)+(SELECT coalesce(sum(stored_bytes),0) FROM ota_deployments)+(SELECT coalesce(sum(stored_bytes),0) FROM ota_deployment_assets) BEGIN SELECT RAISE(ABORT,'invalid capacity accounting'); END;
CREATE TRIGGER github_connections_capacity BEFORE INSERT ON github_connections WHEN NOT EXISTS(SELECT 1 FROM flora_capacity WHERE payload_bytes+NEW.stored_bytes<=134217728) BEGIN SELECT RAISE(ABORT,'flora capacity exceeded'); END;
CREATE TRIGGER github_connections_account AFTER INSERT ON github_connections BEGIN UPDATE flora_capacity SET payload_bytes=payload_bytes+NEW.stored_bytes WHERE singleton=1; END;
CREATE TRIGGER github_connections_update BEFORE UPDATE ON github_connections BEGIN SELECT RAISE(ABORT,'immutable operations'); END;
CREATE TRIGGER github_connections_delete BEFORE DELETE ON github_connections BEGIN SELECT RAISE(ABORT,'immutable operations'); END;
CREATE TRIGGER github_connections_replace BEFORE INSERT ON github_connections WHEN EXISTS(SELECT 1 FROM github_connections WHERE owner_id=NEW.owner_id AND app_id=NEW.app_id AND version=NEW.version) BEGIN SELECT RAISE(ABORT,'immutable operations'); END;
CREATE TRIGGER github_detections_capacity BEFORE INSERT ON github_detections WHEN NOT EXISTS(SELECT 1 FROM flora_capacity WHERE payload_bytes+NEW.stored_bytes<=134217728) BEGIN SELECT RAISE(ABORT,'flora capacity exceeded'); END;
CREATE TRIGGER github_detections_account AFTER INSERT ON github_detections BEGIN UPDATE flora_capacity SET payload_bytes=payload_bytes+NEW.stored_bytes WHERE singleton=1; END;
CREATE TRIGGER github_detections_update BEFORE UPDATE ON github_detections BEGIN SELECT RAISE(ABORT,'immutable operations'); END;
CREATE TRIGGER github_detections_delete BEFORE DELETE ON github_detections BEGIN SELECT RAISE(ABORT,'immutable operations'); END;
CREATE TRIGGER github_detections_replace BEFORE INSERT ON github_detections WHEN EXISTS(SELECT 1 FROM github_detections WHERE owner_id=NEW.owner_id AND app_id=NEW.app_id AND id=NEW.id) BEGIN SELECT RAISE(ABORT,'immutable operations'); END;
CREATE TRIGGER ota_assets_capacity BEFORE INSERT ON ota_assets WHEN NOT EXISTS(SELECT 1 FROM flora_capacity WHERE payload_bytes+NEW.stored_bytes<=134217728) BEGIN SELECT RAISE(ABORT,'flora capacity exceeded'); END;
CREATE TRIGGER ota_assets_account AFTER INSERT ON ota_assets BEGIN UPDATE flora_capacity SET payload_bytes=payload_bytes+NEW.stored_bytes WHERE singleton=1; END;
CREATE TRIGGER ota_assets_update BEFORE UPDATE ON ota_assets BEGIN SELECT RAISE(ABORT,'immutable operations'); END;
CREATE TRIGGER ota_assets_delete BEFORE DELETE ON ota_assets BEGIN SELECT RAISE(ABORT,'immutable operations'); END;
CREATE TRIGGER ota_assets_replace BEFORE INSERT ON ota_assets WHEN EXISTS(SELECT 1 FROM ota_assets WHERE owner_id=NEW.owner_id AND app_id=NEW.app_id AND hash=NEW.hash) BEGIN SELECT RAISE(ABORT,'immutable operations'); END;
CREATE TRIGGER ota_asset_chunks_capacity BEFORE INSERT ON ota_asset_chunks WHEN NOT EXISTS(SELECT 1 FROM flora_capacity WHERE payload_bytes+NEW.stored_bytes<=134217728) BEGIN SELECT RAISE(ABORT,'flora capacity exceeded'); END;
CREATE TRIGGER ota_asset_chunks_account AFTER INSERT ON ota_asset_chunks BEGIN UPDATE flora_capacity SET payload_bytes=payload_bytes+NEW.stored_bytes WHERE singleton=1; END;
CREATE TRIGGER ota_asset_chunks_update BEFORE UPDATE ON ota_asset_chunks BEGIN SELECT RAISE(ABORT,'immutable operations'); END;
CREATE TRIGGER ota_asset_chunks_delete BEFORE DELETE ON ota_asset_chunks BEGIN SELECT RAISE(ABORT,'immutable operations'); END;
CREATE TRIGGER ota_asset_chunks_replace BEFORE INSERT ON ota_asset_chunks WHEN EXISTS(SELECT 1 FROM ota_asset_chunks WHERE owner_id=NEW.owner_id AND app_id=NEW.app_id AND hash=NEW.hash AND chunk_index=NEW.chunk_index) BEGIN SELECT RAISE(ABORT,'immutable operations'); END;
CREATE TRIGGER ota_deployments_capacity BEFORE INSERT ON ota_deployments WHEN NOT EXISTS(SELECT 1 FROM flora_capacity WHERE payload_bytes+NEW.stored_bytes<=134217728) BEGIN SELECT RAISE(ABORT,'flora capacity exceeded'); END;
CREATE TRIGGER ota_deployments_account AFTER INSERT ON ota_deployments BEGIN UPDATE flora_capacity SET payload_bytes=payload_bytes+NEW.stored_bytes WHERE singleton=1; END;
CREATE TRIGGER ota_deployments_update BEFORE UPDATE ON ota_deployments BEGIN SELECT RAISE(ABORT,'immutable operations'); END;
CREATE TRIGGER ota_deployments_delete BEFORE DELETE ON ota_deployments BEGIN SELECT RAISE(ABORT,'immutable operations'); END;
CREATE TRIGGER ota_deployments_replace BEFORE INSERT ON ota_deployments WHEN EXISTS(SELECT 1 FROM ota_deployments WHERE owner_id=NEW.owner_id AND app_id=NEW.app_id AND (id=NEW.id OR request_key=NEW.request_key)) BEGIN SELECT RAISE(ABORT,'immutable operations'); END;
CREATE TRIGGER ota_deployment_assets_capacity BEFORE INSERT ON ota_deployment_assets WHEN NOT EXISTS(SELECT 1 FROM flora_capacity WHERE payload_bytes+NEW.stored_bytes<=134217728) BEGIN SELECT RAISE(ABORT,'flora capacity exceeded'); END;
CREATE TRIGGER ota_deployment_assets_account AFTER INSERT ON ota_deployment_assets BEGIN UPDATE flora_capacity SET payload_bytes=payload_bytes+NEW.stored_bytes WHERE singleton=1; END;
CREATE TRIGGER ota_deployment_assets_update BEFORE UPDATE ON ota_deployment_assets BEGIN SELECT RAISE(ABORT,'immutable operations'); END;
CREATE TRIGGER ota_deployment_assets_delete BEFORE DELETE ON ota_deployment_assets BEGIN SELECT RAISE(ABORT,'immutable operations'); END;
CREATE TRIGGER ota_deployment_assets_replace BEFORE INSERT ON ota_deployment_assets WHEN EXISTS(SELECT 1 FROM ota_deployment_assets WHERE owner_id=NEW.owner_id AND app_id=NEW.app_id AND deployment_id=NEW.deployment_id AND hash=NEW.hash) BEGIN SELECT RAISE(ABORT,'immutable operations'); END;
CREATE TRIGGER github_connection_sequence BEFORE INSERT ON github_connections WHEN NEW.version<>coalesce((SELECT max(version)+1 FROM github_connections WHERE owner_id=NEW.owner_id AND app_id=NEW.app_id),1) BEGIN SELECT RAISE(ABORT,'connection version conflict'); END;
CREATE TRIGGER ota_chunk_binding BEFORE INSERT ON ota_asset_chunks WHEN NOT EXISTS(SELECT 1 FROM ota_assets WHERE owner_id=NEW.owner_id AND app_id=NEW.app_id AND hash=NEW.hash AND NEW.chunk_index<chunk_count) BEGIN SELECT RAISE(ABORT,'asset chunk mismatch'); END;
CREATE TRIGGER ota_asset_complete BEFORE INSERT ON ota_deployment_assets WHEN NOT EXISTS(SELECT 1 FROM ota_assets a WHERE a.owner_id=NEW.owner_id AND a.app_id=NEW.app_id AND a.hash=NEW.hash AND a.chunk_count=(SELECT count(*) FROM ota_asset_chunks c WHERE c.owner_id=a.owner_id AND c.app_id=a.app_id AND c.hash=a.hash) AND a.byte_length=(SELECT coalesce(sum(byte_length),0) FROM ota_asset_chunks c WHERE c.owner_id=a.owner_id AND c.app_id=a.app_id AND c.hash=a.hash)) BEGIN SELECT RAISE(ABORT,'incomplete asset'); END;
CREATE INDEX ota_latest ON ota_deployments(owner_id,app_id,channel,runtime_version,platform,created_at DESC,id DESC);
CREATE INDEX github_detection_history ON github_detections(owner_id,app_id,created_at DESC,id DESC);
CREATE TRIGGER github_connection_binding BEFORE INSERT ON github_connections WHEN json_extract(NEW.data,'$.appId') IS NOT NEW.app_id OR json_extract(NEW.data,'$.version') IS NOT NEW.version BEGIN SELECT RAISE(ABORT,'connection version conflict'); END;
CREATE TRIGGER github_detection_binding BEFORE INSERT ON github_detections WHEN json_extract(NEW.data,'$.id') IS NOT NEW.id OR json_extract(NEW.data,'$.appId') IS NOT NEW.app_id OR json_extract(NEW.data,'$.detectedAt') IS NOT NEW.created_at OR NOT EXISTS(SELECT 1 FROM applications a JOIN github_connections c ON c.owner_id=a.owner_id AND c.app_id=a.id WHERE a.owner_id=NEW.owner_id AND a.id=NEW.app_id AND a.root_directory=json_extract(NEW.data,'$.rootDirectory') AND c.version=(SELECT max(version) FROM github_connections WHERE owner_id=NEW.owner_id AND app_id=NEW.app_id) AND json_extract(NEW.data,'$.connection')=json(c.data)) BEGIN SELECT RAISE(ABORT,'detection connection mismatch'); END;
CREATE TRIGGER ota_asset_binding BEFORE INSERT ON ota_assets WHEN json_extract(NEW.data,'$.id') IS NOT 'asset_'||NEW.hash OR json_extract(NEW.data,'$.appId') IS NOT NEW.app_id OR json_extract(NEW.data,'$.digest') IS NOT NEW.hash OR json_extract(NEW.data,'$.size') IS NOT NEW.byte_length OR json_extract(NEW.data,'$.contentType') IS NOT NEW.content_type OR NEW.chunk_count<>(NEW.byte_length+524287)/524288 BEGIN SELECT RAISE(ABORT,'asset chunk mismatch'); END;
CREATE TRIGGER ota_deployment_binding BEFORE INSERT ON ota_deployments WHEN json_extract(NEW.data,'$.id') IS NOT NEW.id OR json_extract(NEW.data,'$.appId') IS NOT NEW.app_id OR json_extract(NEW.data,'$.requestKey') IS NOT NEW.request_key OR json_extract(NEW.data,'$.channel') IS NOT NEW.channel OR json_extract(NEW.data,'$.runtimeVersion') IS NOT NEW.runtime_version OR json_extract(NEW.data,'$.platform') IS NOT NEW.platform OR json_extract(NEW.data,'$.createdAt') IS NOT NEW.created_at OR NOT EXISTS(SELECT 1 FROM github_detections d WHERE d.owner_id=NEW.owner_id AND d.app_id=NEW.app_id AND d.id=json_extract(NEW.data,'$.detectionId') AND json_extract(d.data,'$.commitSha')=json_extract(NEW.data,'$.commitSha') AND json_extract(d.data,'$.framework') IN ('expo','react-native') AND json_extract(d.data,'$.updatesEnabled')=1 AND json_extract(d.data,'$.runtimeVersion')=NEW.runtime_version AND EXISTS(SELECT 1 FROM json_each(d.data,'$.platforms') WHERE value=NEW.platform)) BEGIN SELECT RAISE(ABORT,'deployment provenance mismatch'); END;
CREATE TRIGGER ota_reference_binding BEFORE INSERT ON ota_deployment_assets WHEN NOT EXISTS(SELECT 1 FROM ota_deployments d JOIN ota_assets a ON a.owner_id=d.owner_id AND a.app_id=d.app_id WHERE d.owner_id=NEW.owner_id AND d.app_id=NEW.app_id AND d.id=NEW.deployment_id AND a.hash=NEW.hash AND ((json_extract(d.data,'$.launchAssetId')='asset_'||a.hash AND json_extract(d.data,'$.launchAsset')=json(a.data)) OR EXISTS(SELECT 1 FROM json_each(d.data,'$.assets') WHERE json_extract(value,'$.id')='asset_'||a.hash AND json(value)=json(a.data)))) BEGIN SELECT RAISE(ABORT,'deployment provenance mismatch'); END;
CREATE TRIGGER ota_app_capacity BEFORE INSERT ON ota_assets WHEN (SELECT count(*) FROM ota_assets WHERE owner_id=NEW.owner_id AND app_id=NEW.app_id)>=128 OR (SELECT coalesce(sum(byte_length),0) FROM ota_assets WHERE owner_id=NEW.owner_id AND app_id=NEW.app_id)+NEW.byte_length>67108864 BEGIN SELECT RAISE(ABORT,'flora capacity exceeded'); END;
CREATE TRIGGER ota_connection_current BEFORE INSERT ON ota_deployments WHEN NOT EXISTS(SELECT 1 FROM github_detections d JOIN github_connections c ON c.owner_id=d.owner_id AND c.app_id=d.app_id WHERE d.owner_id=NEW.owner_id AND d.app_id=NEW.app_id AND d.id=json_extract(NEW.data,'$.detectionId') AND c.version=(SELECT max(version) FROM github_connections WHERE owner_id=NEW.owner_id AND app_id=NEW.app_id) AND json_extract(d.data,'$.connection')=json(c.data)) BEGIN SELECT RAISE(ABORT,'deployment provenance mismatch'); END;
CREATE TRIGGER github_connection_timestamp BEFORE INSERT ON github_connections WHEN EXISTS(SELECT 1 FROM github_connections WHERE owner_id=NEW.owner_id AND app_id=NEW.app_id AND json_extract(data,'$.connectedAt')>json_extract(NEW.data,'$.connectedAt')) BEGIN SELECT RAISE(ABORT,'connection version conflict'); END;
-- Expo clients order manifests by creation time. Concurrent publications that
-- observed the same previous timestamp must conflict rather than create ties.
CREATE TRIGGER ota_monotonic_timestamp BEFORE INSERT ON ota_deployments WHEN EXISTS(SELECT 1 FROM ota_deployments WHERE owner_id=NEW.owner_id AND app_id=NEW.app_id AND channel=NEW.channel AND runtime_version=NEW.runtime_version AND platform=NEW.platform AND created_at>=NEW.created_at) BEGIN SELECT RAISE(ABORT,'deployment timestamp conflict'); END;
